mapper.select:
		SELECT DISTINCT psv.PORTFOLIO_ID "finprodId",tt.VAL_DATE "valDate"
		FROM PTL_SEC_VALUTION psv
		LEFT JOIN FIN_PRODUCT fp
		ON fp.FINPROD_ID = psv.FINPROD_ID
		AND fp.FINPROD_TYPE2='F17'
		LEFT JOIN FIN_PRODUCT fp1
		ON fp1.FINPROD_MARKET_ID = psv.PORTFOLIO_ID
		LEFT JOIN (
			SELECT PTL_ID,max(VAL_DATE) VAL_DATE from(
				SELECT PORTFOLIO_ID PTL_ID,min(VIDT.VALDATE) VAL_DATE
				FROM VALTBL_IMPORT_DATE_TRACE VIDT
				WHERE
					VIDT.VALDATE>=#{dateMin,jdbcType=DATE}
					AND VIDT.VALDATE < #{dateMax,jdbcType=DATE}
					AND VIDT.IMPDATE = #{dateMax,jdbcType=DATE}

                        AND	VIDT.CREATE_DEPT = #{deptCode,jdbcType=VARCHAR}

				GROUP BY PORTFOLIO_ID
			)GROUP BY PTL_ID
		)tt
		ON tt.PTL_ID = fp.FINPROD_MARKET_ID
